@module library  src=library.lua  loc=201  mode=chunk  self=lib
@deps cm, synthetic

# Imports
  @require util = 'util'  @ 4

# Private state
  @state lib = {}  @ 9

# Private functions
  -- Tier reads
  @fn synth(key)  @ 13
  @fn projectTier(key)  @ 14
  @fn libraryTier(key)  @ 15
  @fn factoryTier(key)  @ 16
  @fn sourceOf(key, name)  @ 20-22
      -- Publishable/revertable source for a name: the library copy, never the
      -- project copy. (The factory catalogue is a seed source, not a live source.)
  -- Tier writes
  @fn checkLevel(level)  @ 27-31
      -- The tiers a caller may name: factory is a seed source, not somewhere a name lives.
  @fn writeTier(level, key, name, value)  @ 34-38
      -- Read-modify-write a whole tier through one cm:set; cm deep-copies the value in.
  -- Names
  @fn sortedNames(tier, drop)  @ 42-49

# Public API (lib.*)
  @api lib.names(key)  @ 52-58
      @contract  { project, library } sorted names; synthetic floor dropped, no cross-dedup  @ 51
  -- Reads
  @api lib.getAt(key, level, name)  @ 63-66
      @contract  deep copy from the named tier alone; nil where that tier lacks the name  @ 62
  @api lib.modified(key, name)  @ 69-75
      @contract  true iff a project copy and a same-named source both exist and differ (util.deepEq)  @ 68
  -- Localize / fork
  @api lib.localize(key, name)  @ 80-87
      @contract  copy resolvable entry (library|factory floor) into project; no-op if synthetic/proj copy  @ 79
  @api lib.forkToProject(key, name)  @ 90-93
      @contract  localize then return the editable project copy  @ 89
  -- Author
  @api lib.save(key, level, name, value)  @ 98-102
      @contract  write a name into the named tier (cm:set deep-copies); synthetic names never  @ 97
  -- Publish / revert
  @api lib.publish(key, name)  @ 107-110
      @contract  project copy -> library tier (deepClone via cm:set); no-op when there is no project copy  @ 106
  @api lib.publishOverwrites(key, name)  @ 113-119
      @contract  true iff publish would overwrite a divergent library copy (both tiers exist and differ)  @ 112
  @api lib.revert(key, name)  @ 122-125
      @contract  library source -> project, discarding drift; no-op if no library copy exists  @ 121
  -- Factory seed / reload
  @api lib.seedIfEmpty(key)  @ 130-138
      @contract  stock an empty library tier from the factory catalogue; no-op once it holds anything  @ 129
  @api lib.reloadPlan(key)  @ 141-154
      @contract  { add = names in factory not library, overwrite = present but divergent }; both sorted  @ 140
  @api lib.factoryOverwrites(key, name)  @ 157-162
      @contract  true iff a factory import would overwrite a divergent library copy (both exist, differ)  @ 156
  @api lib.importFactory(key, name)  @ 165-169
      @contract  copy one factory entry into the library tier (deep-clone via cm:set); synthetic never  @ 164
  -- Tidy / delete
  @api lib.tidy(key, inUse)  @ 174-189
      @contract  drop project entries deepEq their source and not in inUse; single cm:set; returns removed  @ 173
  @api lib.delete(key, level, name)  @ 192-199
      @contract  remove name from tier level (project|global); synthetic names never  @ 191

# Uses (outbound edges)
  @use call    cm:defaultFor  @ factoryTier:16
  @use call    cm:getAt  @ projectTier:14 libraryTier:15 writeTier:35 getAt:65 tidy:176 delete:195
  @use call    cm:set  @ writeTier:37 seedIfEmpty:137 tidy:187 delete:198
  @use call    util.add  @ sortedNames:45 reloadPlan:148,149 tidy:181
  @use call    util.deepEq  @ modified:74 publishOverwrites:118 reloadPlan:149 factoryOverwrites:161 tidy:180
  @use require util  @ <load>:4

# Calls (intra-file)
  @call checkLevel  @ getAt:64 save:99 delete:193
  @call factoryTier  @ localize:85 seedIfEmpty:134 reloadPlan:145 factoryOverwrites:158 importFactory:167
  @call lib.localize  @ forkToProject:91
  @call libraryTier  @ sourceOf:21 names:56 localize:85 publishOverwrites:116 seedIfEmpty:131 reloadPlan:142 factoryOverwrites:159
  @call projectTier  @ names:55 modified:70 localize:82 forkToProject:92 publish:108 publishOverwrites:115
  @call sortedNames  @ names:55,56
  @call sourceOf  @ modified:72 revert:123 tidy:179
  @call synth  @ names:53 localize:81 save:100 seedIfEmpty:132 reloadPlan:143 importFactory:166 delete:194
  @call writeTier  @ localize:86 save:101 publish:109 revert:124 importFactory:168

